fn assert_native_resolution(root: &Path) {
    let cargo_out = Command::new("cargo")
        .args(["metadata", "--locked", "--offline", "--format-version", "1"])
        .current_dir(root)
        .output()
        .unwrap();
    assert!(
    run_pnpm(
        &root.join("packages/app"),
        &["pack", "--pack-destination", "../../packed"],
    );
    let archives: Vec<_> = fs::read_dir(root.join("packed"))
        .unwrap()
        .map(|entry| entry.unwrap().path())
        .collect();
    assert_eq!(archives.len(), 1);
    let output = Command::new("tar")
        .arg("-xOf")
        .arg(&archives[0])
        .arg("package/package.json")
        .output()
        .unwrap();
    assert!(output.status.success(), "{}", String::from_utf8_lossy(&output.stderr));
    serde_json::from_slice(&output.stdout).unwrap()
}

fn assert_pnpm_protocols_and_pack(root: &Path, snapshot: bool) {
    let app_path = root.join("packages/app/package.json");
    let app = read_native_package(&app_path);
    let lib = read_native_package(&root.join("packages/lib/package.json"));
    let version = lib["version"].as_str().unwrap();
    if snapshot {
        assert!(version.starts_with("0.0.0-canary-"), "{version}");
        let locator = IgnoreWalkLocator::new(root);
        let runner = callisto_fixtures::git::GitRunner;
        let ws = Workspace::load(root.to_path_buf(), &locator, &runner).expect("workspace must load");

        let (plan, _report) = plan_snapshot(&ws, "canary").expect("plan_snapshot must succeed");

        let permit = callisto_model::ApplyPermit::force_for_tests();
        let opts = crate::apply::ApplyOptions::default();
        crate::apply::apply_version_plan(root, &plan, &runner, &opts, &permit).expect("apply must succeed");

        let target_dir = tmp.path().join("target");
        let output = std::process::Command::new("cargo")
            .args(["metadata", "--no-deps", "--format-version", "1"])
            .env("CARGO_TARGET_DIR", &target_dir)
            .current_dir(root)
            .output()
            .expect("cargo must be installed");

        assert!(
            output.status.success(),
            "cargo metadata must succeed after snapshot rewrites `core`'s spec; stderr: {}",
            String::from_utf8_lossy(&output.stderr)
        );
    }
}

